<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700&display=swap');

        body {
            font-family: 'Roboto', system-ui, sans-serif;
            margin: 0;
            padding: 0;
            background: #ffffff;
            color: #000000;
            line-height: 1.4;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 40px 60px;
        }

        h1 {
            font-size: 28px;
            font-weight: 700;
            margin: 0 0 20px 0;
            text-align: center;
            letter-spacing: 1px;
        }

        h2 {
            font-size: 22px;
            font-weight: 700;
            margin: 30px 0 10px 0;
            border-bottom: 2px solid #cccccc;
            padding-bottom: 5px;
        }

        p {
            font-size: 16px;
            margin: 8px 0;
        }

        .placeholder {
            width: 100%;
            height: 180px;
            background-color: #f5f5f5;
            border: 1px dashed #999999;
            margin: 15px 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            color: #666666;
            font-style: italic;
        }

        .columns {
            display: flex;
            gap: 30px;
        }

        .column {
            flex: 1;
        }

        .side-by-side {
            display: flex;
            gap: 20px;
            margin: 20px 0;
        }

        .label {
            font-weight: 500;
            width: 120px;
            flex-shrink: 0;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
        }

        th, td {
            border: 1px solid #000000;
            padding: 8px;
            text-align: left;
        }

        th {
            background-color: #f0f0f0;
            font-weight: 500;
